/**
 * AMC-CANON-1 deterministic encoding and hashing.
 *
 * Byte-for-byte twin of `services/langgraph/agency/execution/canonical.py`
 * (Python is the reference). `tests/fixtures/amc-canon-1.json` is generated by
 * Python and every entry must be reproduced here; see `tests/parity.test.ts`.
 *
 * One deliberate difference: a JS `number` cannot say whether it was an int or
 * a float. An integral `number` (or a `bigint`) encodes as an int, a non-integral
 * one as a float, and an integral float (Python `2.0`) must be wrapped in
 * `CanonicalFloat`. Integral numbers outside the safe-integer range are refused;
 * pass a `bigint` instead.
 */

export const HASH_PROTOCOL = 'AMC-CANON-1';

export class CanonicalizationError extends Error {
  override name = 'CanonicalizationError';
}

/** A float that must encode as a float even when its value is integral. */
export class CanonicalFloat {
  constructor(readonly value: number) {}
}

export type CanonicalValue =
  | null
  | boolean
  | number
  | bigint
  | string
  | Uint8Array
  | CanonicalFloat
  | readonly CanonicalValue[]
  | ReadonlyMap<string, CanonicalValue>
  | { readonly [key: string]: CanonicalValue };

export interface ManifestFile {
  readonly path: string;
  readonly byte_hash: string;
  readonly size: number;
  readonly media_type?: string | null;
}

const UTF8 = new TextEncoder();
const LONE_SURROGATE = /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/;

function ascii(text: string): Uint8Array {
  return UTF8.encode(text);
}

function utf8(text: string): Uint8Array {
  if (LONE_SURROGATE.test(text)) {
    throw new CanonicalizationError('strings must be well-formed UTF-16 (lone surrogate)');
  }
  return UTF8.encode(text);
}

function concat(chunks: readonly Uint8Array[]): Uint8Array {
  const out = new Uint8Array(chunks.reduce((n, c) => n + c.length, 0));
  let offset = 0;
  for (const chunk of chunks) {
    out.set(chunk, offset);
    offset += chunk.length;
  }
  return out;
}

function compareBytes(a: Uint8Array, b: Uint8Array): number {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i += 1) {
    const diff = (a[i] ?? 0) - (b[i] ?? 0);
    if (diff !== 0) return diff;
  }
  return a.length - b.length;
}

/** Places the decimal point in shortest round-trip digits; mirrors Decimal.normalize() + format "f". */
function positional(digits: string, exponent: number): string {
  const pointAt = exponent + 1;
  if (pointAt <= 0) return `0.${'0'.repeat(-pointAt)}${digits}`;
  if (pointAt >= digits.length) return digits + '0'.repeat(pointAt - digits.length);
  return `${digits.slice(0, pointAt)}.${digits.slice(pointAt)}`;
}

/** Python `_decimal_text`: plain positional notation, no exponent, no trailing zeros, -0 is "0". */
export function decimalText(value: number): string {
  if (!Number.isFinite(value)) {
    throw new CanonicalizationError('non-finite floats are not canonicalizable');
  }
  if (value === 0) return '0';
  const [mantissa = '', exponent = '0'] = value.toExponential().split('e');
  const digits = mantissa.replace('-', '').replace('.', '');
  return (value < 0 ? '-' : '') + positional(digits, Number(exponent));
}

function lengthPrefixed(tag: string, raw: Uint8Array): Uint8Array {
  return concat([ascii(`${tag}${raw.length}:`), raw]);
}

function encodeNumber(value: number): Uint8Array {
  if (!Number.isInteger(value)) return ascii(`F${decimalText(value)};`);
  if (!Number.isSafeInteger(value)) {
    throw new CanonicalizationError('integral numbers beyond 2^53 must be passed as bigint');
  }
  return ascii(`I${value};`);
}

function isPlainObject(value: object): value is { readonly [key: string]: CanonicalValue } {
  const proto: unknown = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function entriesOf(value: object): Array<[string, unknown]> {
  if (value instanceof Map) {
    const entries: Array<[unknown, unknown]> = [...value.entries()];
    for (const [key] of entries) {
      if (typeof key !== 'string') throw new CanonicalizationError('mapping keys must be strings');
    }
    return entries as Array<[string, unknown]>;
  }
  return Object.entries(value);
}

function encodeMapping(value: object): Uint8Array {
  const entries = entriesOf(value).map(([key, item]): [Uint8Array, unknown] => [utf8(key), item]);
  entries.sort(([a], [b]) => compareBytes(a, b));
  const parts = entries.flatMap(([key, item]) => [lengthPrefixed('S', key), encode(item)]);
  return concat([ascii(`D${entries.length}:`), ...parts]);
}

function encodeObject(value: object): Uint8Array {
  if (value instanceof CanonicalFloat) return ascii(`F${decimalText(value.value)};`);
  if (value instanceof Uint8Array) return lengthPrefixed('Y', value);
  if (Array.isArray(value)) {
    const items: readonly unknown[] = value;
    return concat([ascii(`L${items.length}:`), ...items.map(encode)]);
  }
  if (value instanceof Map || isPlainObject(value)) return encodeMapping(value);
  throw new CanonicalizationError(`unsupported canonical type: ${value.constructor.name}`);
}

function encode(value: unknown): Uint8Array {
  if (value === null) return ascii('N');
  if (value === true) return ascii('B1');
  if (value === false) return ascii('B0');
  if (typeof value === 'bigint') return ascii(`I${value.toString()};`);
  if (typeof value === 'number') return encodeNumber(value);
  if (typeof value === 'string') return lengthPrefixed('S', utf8(value));
  if (typeof value === 'object') return encodeObject(value);
  throw new CanonicalizationError(`unsupported canonical type: ${typeof value}`);
}

/** The protocol header, a NUL, then the type-tagged, length-prefixed encoding of `value`. */
export function canonicalBytes(value: CanonicalValue): Uint8Array {
  return concat([ascii(HASH_PROTOCOL), new Uint8Array([0]), encode(value)]);
}

function toHex(bytes: Uint8Array): string {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
}

/** SHA-256 hex digest of raw bytes (Web Crypto: Node 20+ and browsers). */
export async function hashBinary(data: Uint8Array): Promise<string> {
  const digest = await globalThis.crypto.subtle.digest('SHA-256', new Uint8Array(data));
  return toHex(new Uint8Array(digest));
}

export async function canonicalHash(value: CanonicalValue): Promise<string> {
  return hashBinary(canonicalBytes(value));
}

function normalizeManifestFile(file: ManifestFile): { [key: string]: CanonicalValue } {
  if (!Number.isSafeInteger(file.size)) {
    throw new CanonicalizationError('manifest file size must be an integer');
  }
  return {
    path: String(file.path),
    byte_hash: String(file.byte_hash),
    size: file.size,
    media_type: String(file.media_type || 'application/octet-stream'),
  };
}

/** Python `hash_multifile_manifest`: normalize each entry, sort by UTF-8 path bytes, hash the list. */
export async function hashMultifileManifest(files: readonly ManifestFile[]): Promise<string> {
  const normalized = files.map(normalizeManifestFile);
  normalized.sort((a, b) => compareBytes(utf8(String(a.path)), utf8(String(b.path))));
  return canonicalHash(normalized);
}
